"use client";
import * as React from "react";
import { cn } from "../lib/cn";

export interface FieldsetProps extends Omit<React.FieldsetHTMLAttributes<HTMLFieldSetElement>, "title"> {
  legend?: React.ReactNode;
  /** Uitleg onder de titel. */
  description?: React.ReactNode;
  /** Kader rond de groep in plaats van alleen een kopregel. */
  bordered?: boolean;
  /** Velden naast elkaar in plaats van onder elkaar. */
  row?: boolean;
}

/**
 * Fieldset — groepje bij elkaar horende velden met een gedeelde titel.
 * Gebruikt het echte fieldset-element, dus `disabled` zet alles erin uit.
 */
export const Fieldset = React.forwardRef<HTMLFieldSetElement, FieldsetProps>(function Fieldset(
  { legend, description, bordered, row, className, children, ...rest },
  ref
) {
  return (
    <fieldset
      ref={ref}
      className={cn("pxui-fieldset", bordered && "pxui-fieldset-bordered", className)}
      {...rest}
    >
      {legend && <legend className="pxui-fieldset-legend">{legend}</legend>}
      {description && <p className="pxui-fieldset-description">{description}</p>}
      <div className={cn("pxui-fieldset-velden", row && "pxui-fieldset-row")}>{children}</div>
    </fieldset>
  );
});

/* ============================ Fieldset ============================ */
.pxui-fieldset { min-width: 0; margin: 0; padding: 0; border: none; }

.pxui-fieldset-legend {
  padding: 0; font-size: 13.5px; font-weight: 650; color: var(--text);
}
.pxui-fieldset-description {
  margin-top: 3px; font-size: 12.5px; color: var(--text-3); line-height: 1.5;
}
.pxui-fieldset-velden { display: flex; flex-direction: column; gap: 12px; margin-top: 12px; }
.pxui-fieldset-row { flex-direction: row; flex-wrap: wrap; align-items: flex-end; }
.pxui-fieldset-row > * { flex: 1 1 180px; min-width: 0; }

.pxui-fieldset-bordered {
  padding: 16px 18px 18px; border: 1px solid var(--border); border-radius: var(--r-md);
  background: var(--surface);
}
.pxui-fieldset-bordered .pxui-fieldset-legend { padding: 0 6px; margin-left: -6px; }

.pxui-fieldset:disabled { opacity: .6; }
.pxui-fieldset:disabled .pxui-fieldset-velden { pointer-events: none; }
